#include <clang-c-frontend/clang_c_language.h>
#include <ac_config.h>
#include <clang-c-frontend/AST/vfs_paths.h>
#include <util/base/filesystem.h>

#ifdef ESBMC_CLANG_HEADERS_BUNDLED
extern "C"
{
#  include <headers/cheaders.h> /* generated by build system */
#  undef ESBMC_FLAIL
}

static const std::string vfs_prefix = clang_vfs_root() + "/clang";
#endif

void clang_c_languaget::register_bundled()
{
#ifdef ESBMC_CLANG_HEADERS_BUNDLED
  static bool done = false;
  if (done)
    return;
  done = true;

#  define ESBMC_FLAIL(body, size, ...)                                         \
    file_operations::filesystemt::get().add_bundled(                           \
      vfs_prefix + "/include/" #__VA_ARGS__, body, size);
#  include <headers/cheaders.h>
#  undef ESBMC_FLAIL
#endif
}

const std::string &clang_c_languaget::clang_resource_dir()
{
#ifdef ESBMC_CLANG_HEADERS_BUNDLED
  // c2goto has its own main(), so accessors register on demand.
  register_bundled();
  // Inside esbmc_clang_vfs(), never on disk.
  return vfs_prefix;
#else
  // clang headers not bundled, return the path set at compile time
  static const std::string path = ESBMC_CLANG_HEADER_DIR "/..";
  return path;
#endif
}
